// Theme Engine (Light / Dark)
function initTheme() {
  const savedTheme = localStorage.getItem(STORAGE_KEYS.THEME);
  const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  const theme = savedTheme || (prefersDark ? 'dark' : 'light');
  applyTheme(theme);
}

function toggleTheme() {
  const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
  const newTheme = currentTheme === 'light' ? 'dark' : 'light';

  const icon = document.getElementById('theme-icon');
  if (icon) {
    icon.classList.remove('theme-icon-spin');
    void icon.offsetWidth;
    icon.classList.add('theme-icon-spin');
    setTimeout(() => icon.classList.remove('theme-icon-spin'), 320);
  }

  applyTheme(newTheme);
  localStorage.setItem(STORAGE_KEYS.THEME, newTheme);
  showToast(newTheme === 'light' ? '☀️ Включена светлая тема' : '🌙 Включена темная тема');
}

function applyTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);

  // Sync mobile browser status bar theme-color
  const metaTheme = document.querySelector('meta[name="theme-color"]');
  if (metaTheme) {
    metaTheme.setAttribute('content', theme === 'dark' ? '#0a0c10' : '#f8fafc');
  }

  // Update theme toggle button
  // In Dark theme -> show SUN icon with amber accent (action: switch to light)
  // In Light theme -> show MOON icon with solid fill (action: switch to dark)
  const icon = document.getElementById('theme-icon');
  const btn = document.getElementById('theme-toggle-btn');
  if (icon) {
    if (theme === 'dark') {
      icon.innerHTML = '<circle cx="12" cy="12" r="5"></circle><line x1="12" y1="1" x2="12" y2="3"></line><line x1="12" y1="21" x2="12" y2="23"></line><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line><line x1="1" y1="12" x2="3" y2="12"></line><line x1="21" y1="12" x2="23" y2="12"></line><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"></line><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"></line>';
      icon.setAttribute('fill', 'none');
      icon.setAttribute('stroke', 'currentColor');
      icon.style.color = 'var(--accent-amber)';
      if (btn) btn.title = 'Переключить на светлую тему';
    } else {
      icon.innerHTML = '<path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" fill="currentColor"></path>';
      icon.removeAttribute('stroke');
      icon.style.color = 'var(--text-secondary)';
      if (btn) btn.title = 'Переключить на темную тему';
    }
  }
}

// Load data from LocalStorage or seed defaults
function loadStoredData() {
  const storedRecipes = localStorage.getItem(STORAGE_KEYS.RECIPES);
  if (storedRecipes) {
    try {
      const parsed = JSON.parse(storedRecipes);
      const defaultMap = new Map(DEFAULT_RECIPES.map(r => [r.id, r]));
      // Update any default recipe to latest chef specs while preserving custom user recipes
      const updated = parsed.map(r => defaultMap.has(r.id) ? { ...defaultMap.get(r.id) } : r);
      const existingIds = new Set(updated.map(r => r.id));
      const newDefaults = DEFAULT_RECIPES.filter(r => !existingIds.has(r.id));
      state.recipes = [...updated, ...newDefaults];
      saveRecipes();
    } catch (e) {
      state.recipes = DEFAULT_RECIPES;
    }
  } else {
    state.recipes = DEFAULT_RECIPES;
    saveRecipes();
  }

  const storedShopping = localStorage.getItem(STORAGE_KEYS.SHOPPING);
  if (storedShopping) {
    try {
      state.shoppingList = JSON.parse(storedShopping);
      // Ensure each item has a valid category
      state.shoppingList.forEach(item => {
        if (!item.category) {
          const isSpice = (item.source && (item.source.includes('Демьян') || item.source.includes('Спец') || item.source.includes('Базов'))) ||
                          DEMIAN_RECOMMENDED_SPICES.some(s => s.toLowerCase().includes(item.name.toLowerCase()));
          item.category = isSpice ? 'spice' : 'recipe';
        }
      });
    } catch (e) {
      state.shoppingList = [];
    }
  }

  const storedTimers = localStorage.getItem(STORAGE_KEYS.TIMERS);
  if (storedTimers) {
    try {
      state.activeTimers = JSON.parse(storedTimers);
    } catch (e) {
      state.activeTimers = [];
    }
  }

  const storedPlanner = localStorage.getItem(STORAGE_KEYS.PLANNER);
  if (storedPlanner) {
    try {
      state.plannerQueue = JSON.parse(storedPlanner);
    } catch (e) {
      state.plannerQueue = [];
    }
  }

  const storedFavs = localStorage.getItem(STORAGE_KEYS.FAVORITES);
  if (storedFavs) {
    try {
      state.favorites = JSON.parse(storedFavs);
    } catch (e) {
      state.favorites = [];
    }
  }

  const storedMarket = localStorage.getItem(STORAGE_KEYS.MARKET_PREFS);
  if (storedMarket) {
    try {
      state.marketPrefs = { ...DEFAULT_MARKET_PREFS, ...JSON.parse(storedMarket) };
    } catch (e) {
      state.marketPrefs = { ...DEFAULT_MARKET_PREFS };
    }
  } else {
    state.marketPrefs = { ...DEFAULT_MARKET_PREFS };
  }
  currentSearchExportFormat = state.marketPrefs.format || 'plain';
}

function saveFavorites() {
  localStorage.setItem(STORAGE_KEYS.FAVORITES, JSON.stringify(state.favorites));
}

function saveRecipes() {
  localStorage.setItem(STORAGE_KEYS.RECIPES, JSON.stringify(state.recipes));
}

function saveShopping() {
  localStorage.setItem(STORAGE_KEYS.SHOPPING, JSON.stringify(state.shoppingList));
}

function saveTimers() {
  localStorage.setItem(STORAGE_KEYS.TIMERS, JSON.stringify(state.activeTimers));
}

function savePlanner() {
  localStorage.setItem(STORAGE_KEYS.PLANNER, JSON.stringify(state.plannerQueue));
}

function saveMarketPrefs() {
  localStorage.setItem(STORAGE_KEYS.MARKET_PREFS, JSON.stringify(state.marketPrefs));
}

// Navigation between views
function setupNavigation() {
  const navButtons = document.querySelectorAll('.nav-item');
  navButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetTab = btn.dataset.tab;
      switchTab(targetTab);
    });
  });
}

function switchTab(tabId) {
  state.activeTab = tabId;
  document.querySelectorAll('.nav-item').forEach(b => {
    b.classList.toggle('active', b.dataset.tab === tabId);
  });
  document.querySelectorAll('.view-panel').forEach(p => {
    p.classList.toggle('active', p.id === `view-${tabId}`);
  });
  if (tabId === 'favorites') {
    renderFavoritesView();
  } else if (tabId === 'planner') {
    renderPlannerView();
  }
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

