// Butchery Modal Handlers
function openButcheryModal(cutOrRecipeId) {
  const cut = BUTCHERY_CUTS[cutOrRecipeId] || BUTCHERY_CUTS['chuck-primal'];
  const modal = document.getElementById('butchery-modal');
  const title = document.getElementById('butchery-modal-title');
  const body = document.getElementById('butchery-modal-body');
  if (!modal || !title || !body) return;

  title.innerHTML = `🔪 ${cut.title}`;
  
  body.innerHTML = `
    <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 12px; flex-wrap: wrap;">
      <span class="butchery-cut-badge">${cut.badge}</span>
      <span style="font-size: 0.76rem; color: var(--accent-emerald); font-weight: 700;">Нежность: ${cut.tenderness}</span>
      <span style="font-size: 0.76rem; color: var(--accent-amber); font-weight: 600; margin-left: auto;">⏱ ${cut.tempTime}</span>
    </div>

    <div style="font-size: 0.84rem; color: var(--text-secondary); margin-bottom: 12px; line-height: 1.45;">
      ${cut.description}
    </div>

    <div style="background: rgba(255,255,255,0.03); border: 1px solid var(--border-subtle); border-radius: 8px; padding: 8px 12px; margin-bottom: 12px; font-size: 0.78rem;">
      <strong style="color: var(--text-primary);">🧰 Инструмент:</strong> ${cut.tools}
    </div>

    <div class="butchery-diagram-box">${cut.diagram}</div>

    <div style="font-weight: 700; color: var(--text-primary); font-size: 0.88rem; margin: 16px 0 8px;">
      Пошаговый протокол разделки:
    </div>

    ${cut.steps.map(s => `
      <div class="butchery-step">
        <div class="butchery-step-header">
          <span class="butchery-step-num">Шаг ${s.num}</span>
          <strong style="color: var(--text-primary); font-size: 0.86rem;">${s.title}</strong>
        </div>
        <div class="butchery-tech-action">
          <strong>🔪 ДЕЙСТВИЕ:</strong> ${s.action}
        </div>
        <div class="butchery-tech-action" style="border-left-color: #ef4444; margin-top: 6px;">
          <span class="action-warning">⚠️ ОШИБКА:</span> ${s.warning}
        </div>
      </div>
    `).join('')}

    <div style="background: rgba(16, 185, 129, 0.08); border: 1px solid rgba(16, 185, 129, 0.25); border-radius: 10px; padding: 12px; margin-top: 14px; font-size: 0.82rem;">
      <strong style="color: var(--accent-emerald);">🎯 РЕЗУЛЬТАТ:</strong> ${cut.target}
    </div>

    <div style="display: flex; gap: 8px; margin-top: 16px; flex-wrap: wrap;">
      <button class="btn btn-secondary btn-sm" style="flex: 1;" onclick="closeButcheryModal()">
        Закрыть
      </button>
      <button class="btn btn-primary btn-sm" style="flex: 1;" onclick="closeButcheryModal(); switchView('recipes');">
        🥩 Перейти к рецептам
      </button>
    </div>
  `;

  modal.classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeButcheryModal() {
  const modal = document.getElementById('butchery-modal');
  if (modal) {
    modal.classList.remove('active');
  }
  document.body.style.overflow = '';
}

// Image Lightbox Modal Engine
function openImageModal(imgSrc, title, author, source) {
  const modal = document.getElementById('image-lightbox-modal');
  const modalImg = document.getElementById('image-modal-img');
  const modalTitle = document.getElementById('image-modal-title');
  const modalMeta = document.getElementById('image-modal-meta');
  if (!modal || !modalImg) return;

  modalImg.src = imgSrc;
  modalImg.alt = title || 'Фото блюда';
  if (modalTitle) {
    modalTitle.innerHTML = `<span>📸 ${escapeHtml(title || 'Фото блюда')}</span>`;
  }
  if (modalMeta) {
    const srcNote = source ? ` [${escapeHtml(source)}]` : '';
    modalMeta.innerHTML = `
      <div><strong>Автор рецепта:</strong> ${escapeHtml(author || 'Шеф-Лаб / Форум Хлебопечка.ру')}${srcNote}</div>
      <div style="font-size: 0.76rem; color: var(--text-muted); margin-top: 4px;">
        Оригинальная фотография результата приготовления по технологии су-вид.
      </div>
    `;
  }
  modal.classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeImageModal() {
  const modal = document.getElementById('image-lightbox-modal');
  if (modal) {
    modal.classList.remove('active');
  }
  document.body.style.overflow = '';
}

// Global ESC key handler for modals
window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    closeImageModal();
    closeButcheryModal();
  }
});

const APP_VERSION = 'v3.13';

// Show tactile version details toast
function showAppVersionInfo() {
  const isOnline = navigator.onLine ? 'Онлайн 🟢' : 'Оффлайн (PWA кэш) 🟠';
  const swState = (navigator.serviceWorker && navigator.serviceWorker.controller) ? `Активен (${APP_VERSION})` : 'Автономен';
  const count = state.recipes ? state.recipes.length : 0;
  
  showToast(`⚡️ Sous-Vide Chef Lab ${APP_VERSION}\n• Сеть: ${isOnline}\n• Service Worker: ${swState}\n• Техкарт в базе: ${count}\n(Нажмите в меню «Сбросить кэш», если нужно форсировать обновление)`, 4500);
}

// Clear all client caches and force clean reload
async function forceAppUpdate() {
  showToast('🔄 Сброс локального кэша и обновление...', 2500);
  try {
    if ('caches' in window) {
      const keys = await caches.keys();
      await Promise.all(keys.map(k => caches.delete(k)));
    }
    if ('serviceWorker' in navigator) {
      const registrations = await navigator.serviceWorker.getRegistrations();
      for (const reg of registrations) {
        await reg.update();
      }
    }
  } catch (e) {
    console.error('Update cache clear error:', e);
  }
  setTimeout(() => {
    window.location.reload(true);
  }, 600);
}

// Service Worker Registration with Auto-Update
function registerServiceWorker() {
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('./sw.js').then(reg => {
      reg.addEventListener('updatefound', () => {
        const newWorker = reg.installing;
        if (newWorker) {
          newWorker.addEventListener('statechange', () => {
            if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
              showToast('✨ Доступно обновление! Перезагрузка...');
              setTimeout(() => window.location.reload(), 1200);
            }
          });
        }
      });
    }).catch(err => {
      console.log('SW registration note:', err);
    });

    let refreshing = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (!refreshing) {
        refreshing = true;
        window.location.reload();
      }
    });
  }
}

// Boot application
window.addEventListener('DOMContentLoaded', initApp);
